const { spawn } = require('child_process'); const WebSocket = require('ws'); const express = require('express'); const { detectFramework } = require('./utils/detectFramework'); const app = express(); const wss = new WebSocket.Server({ port: 8080 }); const sessions = new Map(); wss.on('connection', (ws, req) => { const sessionId = req.url.split('/')[1]; const projectPath = `/home/sessions/${sessionId}/repo`; const framework = detectFramework(projectPath); const shell = spawn(process.platform === 'win32' ? 'cmd.exe' : 'bash', process.platform === 'win32' ? ['/Q', '/K'] : [], { cwd: projectPath, env: { ...process.env, PORT: String(framework.port), DATABASE_URL: sessions.get(sessionId)?.databaseUrl || '' } }); sessions.set(sessionId, { ...sessions.get(sessionId), shell, framework }); const welcome = `
⚡ Default port from ${framework.name} · Code Shield: ${framework.port}
   Run command : ${framework.cmd}
   Preview URL : https://preview-${sessionId}.up.railway.app

`; ws.send(welcome); shell.stdout.on('data', data => { if (ws.readyState === WebSocket.OPEN) ws.send(data); }); shell.stderr.on('data', data => { if (ws.readyState === WebSocket.OPEN) ws.send(data); }); ws.on('message', data => { try { const msg = JSON.parse(data); if (shell && shell.stdin.writable) shell.stdin.write(msg.data || data); } catch { if (shell && shell.stdin.writable) shell.stdin.write(data); } }); ws.on('close', () => { shell.kill(); sessions.delete(sessionId); }); }); app.listen(3001, () => console.log('REST API on 3001')); module.exports = { app };

